    pattern = re.compile(r'^(4e 43 32 36)(.*)$')

    for line in lines:
        match = pattern.match(line.strip())
        if match:
            prefix = match.group(1)
            rest = match.group(2)
            print(f"{prefix} {rest}")

if __name__ == "__main__":
