import struct
MAGIC = b"NC26"
VERSION = 1
HEADER = ">4sBBIIH"
XOR_KEY = b'orchid-icmp-key'
MSG_TYPES = {
1: "HELLO",
2: "TASK",
3: "DATA",
4: "ACK",
5: "BYE",
}
def derive_agent_id(hostname, mac):
seed = f"{hostname}|{mac}".lower().encode()
return struct.unpack(">I", import("hashlib").sha1(seed).digest()[:4])[0]
def decode_blob(blob):
xored = bytes(b ^ XOR_KEY[i % len(XOR_KEY)] for i, b in enumerate(blob))
return gzip.decompress(xored)
def parse_packet(payload):
header_size = struct.calcsize(HEADER)
magic, version, msg_type, agent_id, task_id, chunk_no = struct.unpack(HEADER, payload[
])
