<script>
const $ = (i)=>document.getElementById(i);
let T;
function fmt(s){
  s=Math.max(0,s|0);
  return String(s/60|0).padStart(2,"0")+":"+String(s%60).padStart(2,"0");
}
async function poll(){
  try{
    const d = await (await fetch("/api/status")).json();
    if(d.state==="win"){
      clearInterval(T); $("timer").textContent="--:--";
      $("flagBox").style.display="block"; $("flagText").textContent=d.flag;
      $("mambaBox").style.display="none";
      return;
    }
    if(d.state==="mamba"){
      clearInterval(T); $("timer").textContent="00:00";
      $("mambaBox").style.display="block";
      return;
    }
    $("timer").textContent=fmt(d.remaining);
    if(d.remaining<60) $("timer").classList.add("low");
    else $("timer").classList.remove("low");
  }catch(e){}
}
$("submitBtn").onclick = async ()=>{
  const c=$("wp").value; if(!c){$("msg").textContent="内容为空";return;}
  $("msg").textContent="提交中...";
  try{
    const d = await (await fetch("/api/submit",{method:"POST",
      headers:{"Content-Type":"application/x-www-form-urlencoded"},
      body:new URLSearchParams({content:c})})).json();
    $("msg").textContent=d.msg;
  }catch(e){ $("msg").textContent="网络错误"; }
};
$("resetBtn").onclick = async ()=>{
  await fetch("/api/reset",{method:"POST"});
  $("msg").textContent="";
  $("flagBox").style.display=$("mambaBox").style.display="none";
  $("timer").classList.remove("low");
  clearInterval(T);
  poll(); T=setInterval(poll,1000);
};
poll(); T=setInterval(poll,1000);
</script>
</body>
</html>
"""


review_tbl = {}
user_review = defaultdict(set)
user_draft = defaultdict(set)
db_lock = threading.Lock()


ai_lock = defaultdict(threading.Lock)



executor = ProcessPoolExecutor(max_workers=2)

def _has_nco26_flag(content: str) -> bool:
    RULE = re.compile(
        r"^([A-Za-z]*[0-9]*)*\s*(NCO26\{[^}]*\})\s*([A-Za-z]*[0-9]*)*$",
        re.DOTALL | re.IGNORECASE,
    )
    return bool(RULE.match(content))


@app.get("/robots.txt")
def robots():
    return "User-agent: *\nDisallow: /debug\n", 200, {"Content-Type": "text/plain"}


@app.get("/debug")
def debug():
    try:
        with open(__file__, "r") as f:
            return f.read(), 200, {"Content-Type": "text/plain; charset=utf-8"}
    except Exception:
        return "Unavailable", 500


def uid_of():
    if "uid" not in session:
        session["uid"] = str(uuid.uuid4())
        session["start"] = time.time()
    return session["uid"]


def _ins_review(uid, content):
    wid = str(uuid.uuid4())
    with db_lock:
        review_tbl[wid] = {
            "uid": uid, "content": content,
            "status": "reviewing", "ts": time.time(),
        }
        user_review[uid].add(wid)
    return wid


def _del_review(wid):
    with db_lock:
        w = review_tbl.pop(wid, None)
        if w:
            user_review[w["uid"]].discard(wid)


def user_has_wp(uid):
    with db_lock:
        return bool(user_review.get(uid))

@app.get("/")
def index():
    uid = uid_of()
    return render_template_string(INDEX_HTML, uid_short=uid[:8])


@app.post("/api/submit")
def submit():
    uid = uid_of()
    if time.time() - session["start"] > CONTEST_SECONDS:
        return jsonify(ok=False, msg="比赛已结束，无法提交"), 403
    content = (request.form.get("content") or "").strip()
    if not content:
        return jsonify(ok=False, msg="内容为空"), 400
    if len(content) > 512:
        return jsonify(ok=False, msg="WriteUp 超过 512 字限制"), 400

    lock = ai_lock[uid]
    wid = None
    if not lock.acquire(blocking=True, timeout=0.1):
        wid = _ins_review(uid, content)
        return jsonify(ok=True, msg="你的 WriteUp 已成功提交，待审核")
    try:
        has_flag = executor.submit(_has_nco26_flag, content).result(timeout=30)
        if not has_flag:
            _del_review(wid)
            return jsonify(ok=False, msg="WriteUp 里需要贴上 flag (NCO26{...})")
        if FLAG in content:
            return jsonify(ok=True, msg=f"恭喜你获得了 FLAG！{FLAG}")
        else:
            _del_review(wid)
            return jsonify(ok=False, msg="FLAG不对哦")
    finally:
        lock.release()


@app.get("/api/status")
def status():
    uid = uid_of()
    remaining = max(0, CONTEST_SECONDS - (time.time() - session["start"]))
    if user_has_wp(uid):
        return jsonify(state="win", flag=FLAG)
    if remaining > 0:
        return jsonify(state="running", remaining=int(remaining))
    return jsonify(state="mamba")


@app.post("/api/reset")
def reset():
    uid = uid_of()
    remaining = max(0, CONTEST_SECONDS - (time.time() - session["start"]))
    if remaining > 0:
        return jsonify(ok=False, msg="比赛尚未结束"), 403
    session["start"] = time.time()
    with db_lock:
        for wid in list(user_review.get(uid, set())):
            review_tbl.pop(wid, None)
        user_review[uid] = set()
        user_draft[uid] = set()
    ai_lock[uid] = threading.Lock()
    return jsonify(ok=True, msg="倒计时已重置，状态已清空")


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5005, threaded=True)
