    return ((value << amount) | (value >> (8 - amount))) & 0xFF
def xor_bytes(left, right):
    return bytes(a ^ b for a, b in zip(left, right))
def pad(data):
    pad_len = BLOCK_SIZE - len(data) % BLOCK_SIZE
    return data + bytes([pad_len]) * pad_len
def diffuse(block):
    state = list(block)
    for target, source, rotation in TAPS:
        state[target] = rol8(state[target] ^ state[source], rotation)
    return bytes(state[index] for index in PERMUTATION)

def inverse_diffuse(block):
    inv_permutation = [0] * BLOCK_SIZE
    for i, j in enumerate(PERMUTATION):
        inv_permutation[j] = i
    state = [block[i] for i in inv_permutation]
    for tap in reversed(TAPS):
        target, source, rotation = tap
        state[target] = rol8(state[target], -rotation)
        state[target] ^= state[source]
    return bytes(state)
