def rot13_decode(s: str) -> str:
    # ROT13 is its own inverse
    return s.translate(str.maketrans('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', 'NOPQRSTUVWXYZABCDEFGHIJKLMnopqrstuvwxyzabcdefghijklm'))

decoded_chats = []

with open("output.txt", 'r') as f:
    for line in f:
        if not line.strip():
            continue
        # Split the line to separate role and content
        parts = line.strip().split(': ', 1)
        if len(parts) == 2:
            role = rot13_decode(parts[0])
            content = rot13_decode(parts[1])
            decoded_chats.append({
                "role": role,
                "content": content
            })

# Find the flag from the third message (assistant's response)
for chat in decoded_chats:
    if chat['role'] == 'assistant' and 'Here you are:' in chat['content']:
        # Extract the flag part after "Here you are: "
        flag = chat['content'].replace("Here you are: ", "")
        print(flag)
        break
